template <typename T>
struct Complex {
    T re, im;
    Complex operator*(Complex o) const { return {re * o.re - im * o.im, re * o.im + im * o.re}; }
    Complex operator+(Complex o) const { return {re + o.re, im + o.im}; }
    T norm2() const { return re * re + im * im; }
};

template <typename T>
static inline int escape(Complex<T> c, int maxIter) {
    Complex<T> z{0, 0};
    int it = 0;
    while (z.norm2() <= T(4) && it < maxIter) {
        z = z * z + c;
        ++it;
    }
    return it;
}

extern "C" int iterations(double re, double im, int maxIter) {
    return escape(Complex<double>{re, im}, maxIter);
}

using u8 = unsigned char;

struct Palette { u8 rgb[256][3]; };

constexpr Palette makePalette() {
    Palette p{};
    for (int i = 0; i < 256; i++) {
        double t = i / 255.0;
        p.rgb[i][0] = (u8)(9.0  * (1 - t) * t * t * t * 255.0);
        p.rgb[i][1] = (u8)(15.0 * (1 - t) * (1 - t) * t * t * 255.0);
        p.rgb[i][2] = (u8)(8.5  * (1 - t) * (1 - t) * (1 - t) * t * 255.0);
    }
    return p;
}
static constexpr Palette PAL = makePalette();

extern "C" int red(int i) {
    return PAL.rgb[i & 255][0];
}

extern "C" int red_runtime(int i) {
    double t = (i & 255) / 255.0;
    return (u8)(9.0 * (1 - t) * t * t * t * 255.0);
}

struct Shape {
    virtual double area() const = 0;
};

struct Circle : Shape {
    double r;
    constexpr Circle(double r) : r(r) {}
    double area() const override { return 3.14159265 * r * r; }
};

struct Square : Shape {
    double s;
    constexpr Square(double s) : s(s) {}
    double area() const override { return s * s; }
};

static Circle circle{1.0};
static Square square{2.0};

extern "C" const Shape* pick(int which) {
    return which ? static_cast<const Shape*>(&square) : static_cast<const Shape*>(&circle);
}

extern "C" double area(const Shape* s) {
    return s->area();          // -> call_indirect
}

// -nostdlib: we provide the one runtime hook a pure virtual needs.
extern "C" void __cxa_pure_virtual() { __builtin_trap(); }

